  "Your site and grading language preferences are saved with your account until account data deletion. Translations use the existing AI provider and are cached for up to 24 hours. Translating a result does not change your saved original result or account preferences.": [
    "साइट और ग्रेडिंग भाषा की आपकी प्राथमिकताएँ, खाता डेटा हटाए जाने तक आपके खाते में सहेजी रहती हैं। अनुवाद के लिए मौजूदा AI प्रदाता का उपयोग किया जाता है और अनुवाद 24 घंटे तक कैश में रखे जाते हैं। किसी परिणाम का अनुवाद करने से आपका सहेजा हुआ मूल परिणाम या खाते की प्राथमिकताएँ नहीं बदलतीं।",
    "آپ کی سائٹ اور گریڈنگ کی زبان کی ترجیحات اکاؤنٹ کا ڈیٹا حذف ہونے تک آپ کے اکاؤنٹ میں محفوظ رہتی ہیں۔ ترجمے کے لیے موجودہ AI فراہم کنندہ استعمال ہوتا ہے اور ترجمے 24 گھنٹے تک کیش میں محفوظ رہتے ہیں۔ کسی نتیجے کا ترجمہ کرنے سے آپ کا محفوظ شدہ اصل نتیجہ یا اکاؤنٹ کی ترجیحات تبدیل نہیں ہوتیں۔",
    "Tùy chọn ngôn ngữ trang web và chấm điểm của bạn được lưu cùng tài khoản cho đến khi dữ liệu tài khoản bị xóa. Bản dịch sử dụng nhà cung cấp AI hiện tại và được lưu vào bộ nhớ đệm tối đa 24 giờ. Việc dịch một kết quả không làm thay đổi kết quả gốc đã lưu hoặc tùy chọn tài khoản của bạn.",
    "您的网站语言和评分语言偏好会与您的帐户一同保存，直到帐户数据被删除。翻译使用现有的 AI 提供商，缓存时间最长为 24 小时。翻译结果不会更改已保存的原始结果或帐户偏好。"
  ],
  "Calculation details are unavailable for this saved result.": [
    "इस सहेजे गए परिणाम के लिए गणना का विवरण उपलब्ध नहीं है।",
    "اس محفوظ شدہ نتیجے کے لیے حساب کی تفصیلات دستیاب نہیں ہیں۔",
    "Không có thông tin chi tiết về phép tính cho kết quả đã lưu này.",
    "此已保存结果的计算详情不可用。"
  ],
  "Saved result from an earlier scoring method. It may include a mode adjustment or a narrowed range; compare revisions only with results using the same scoring method.": [
    "पहले की स्कोरिंग विधि से सहेजा गया परिणाम। इसमें मोड समायोजन या सीमित स्कोर रेंज शामिल हो सकती है; संशोधनों की तुलना केवल उसी स्कोरिंग विधि के परिणामों से करें।",
    "پہلے کے اسکورنگ طریقے سے محفوظ کیا گیا نتیجہ۔ اس میں موڈ کی ایڈجسٹمنٹ یا محدود اسکور رینج شامل ہو سکتی ہے؛ ترامیم کا موازنہ صرف اسی اسکورنگ طریقے کے نتائج سے کریں۔",
    "Kết quả đã lưu từ phương pháp chấm điểm trước đó. Kết quả có thể bao gồm điều chỉnh chế độ hoặc thu hẹp khoảng điểm; chỉ so sánh các bản sửa đổi với kết quả dùng cùng phương pháp chấm điểm.",
    "使用先前评分方法保存的结果。结果可能包含模式调整或缩小后的分数范围；请仅与使用相同评分方法的结果比较修订版本。"
  ],
  "Criterion range totals {low}-{high}, divided by the rubric total {total} x 100 and rounded, give {range} / 100. No mode bonus or penalty is added. Individual point scores are separate model estimates; this total uses the range endpoints.": [
    "मानदंडों के रेंज का कुल {low}-{high}, रूब्रिक के कुल {total} से भाग देकर, फिर x 100 से गुणा करके और पूर्णांक में बदलने पर {range} / 100 मिलता है। कोई मोड बोनस या दंड नहीं जोड़ा जाता। हर बिंदु का स्कोर मॉडल के अलग-अलग अनुमान हैं; इस कुल में रेंज के सिरों का उपयोग होता है।",
    "معیار کی رینج کا مجموعہ {low}-{high}، روبریک کے کل {total} سے تقسیم، پھر x 100 سے ضرب اور گول کرنے پر {range} / 100 بنتا ہے۔ موڈ کا کوئی بونس یا جرمانہ شامل نہیں کیا جاتا۔ ہر پوائنٹ کے اسکور ماڈل کے الگ الگ اندازے ہیں؛ اس مجموعی اسکور میں رینج کے آخری پوائنٹس استعمال ہوتے ہیں۔",
    "Tổng khoảng điểm của các tiêu chí là {low}-{high}; chia cho tổng điểm của rubric {total}, nhân x 100 và làm tròn sẽ được {range} / 100. Không cộng thêm điểm thưởng hay trừ điểm theo chế độ. Điểm của từng tiêu chí là các ước tính riêng của mô hình; tổng này dùng hai đầu mút của khoảng điểm.",
    "各项标准的分数范围总计为 {low}-{high}，除以量规总分 {total}，再乘以 x 100 并四舍五入，得出 {range} / 100。不添加模式加分或扣分。各项分数是模型的独立估算；此总分使用范围的两个端点。"
  ],
