    "ہم وقتاً فوقتاً ان شرائط کو اپ ڈیٹ کر سکتے ہیں۔ اپ ڈیٹس کے بعد سروس کا استعمال جاری رکھنے کا مطلب ہے کہ آپ نظرثانی شدہ شرائط قبول کرتے ہیں۔",
