    "قانون کے تحت لازم ہونے کے علاوہ، سبسکرپشن شروع ہونے کے بعد موجودہ بلنگ مدت کے چارجز کا تناسبی حساب سے ریفنڈ نہیں کیا جاتا۔",
    "Trừ trường hợp pháp luật yêu cầu, phí của kỳ thanh toán hiện tại sẽ không được hoàn theo tỷ lệ sau khi gói đăng ký đã bắt đầu.",
    "除法律要求的情况外，订阅开始后，当前账期的费用不按比例退款。"
