    "آپ RubriCheck کو قانونی تعلیمی اور تحریری معاونت کے مقاصد کے لیے استعمال کرنے، اور اپنے اسکول، ادارے اور مقامی قانون کے تقاضوں کی پابندی کرنے سے اتفاق کرتے ہیں۔ آپ کی جمع کرائی گئی مواد کے ذمہ دار آپ ہیں۔",
    "Bạn đồng ý sử dụng RubriCheck cho các mục đích hỗ trợ giáo dục và viết lách hợp pháp, đồng thời tuân thủ các yêu cầu của trường học, cơ sở giáo dục và luật pháp địa phương. Bạn chịu trách nhiệm về nội dung mình gửi.",
