    "RubriCheck، AI کی مدد سے تخمینے اور دوبارہ لکھنے کی تجاویز فراہم کرتا ہے۔ نتائج صرف معلوماتی مقاصد کے لیے ہیں؛ یہ سرکاری گریڈ، ادارہ جاتی فیصلے یا پیشہ ورانہ مشورہ نہیں ہیں۔",
    "RubriCheck cung cấp các ước tính và gợi ý viết lại có hỗ trợ của AI. Kết quả chỉ nhằm mục đích cung cấp thông tin, không phải là điểm số chính thức, quyết định của cơ sở giáo dục hay lời khuyên chuyên môn.",
