  "With your permission, we measure public page visits and evaluation, signup and checkout steps using a pseudonymous browser identifier. We link these steps to a pseudonymous account identifier after verification. We retain only approved campaign names, public landing paths, referrer categories and country when available. Assignment content, names, emails and payment secrets are not sent to analytics providers. Turn optional analytics off using the control at the bottom of the page. Do Not Track and Global Privacy Control disable optional collection.": [
    "आपकी अनुमति से, हम छद्मनाम वाले ब्राउज़र पहचानकर्ता का उपयोग करके सार्वजनिक पेज विज़िट और मूल्यांकन, साइनअप और चेकआउट के चरणों को मापते हैं। सत्यापन के बाद, हम इन चरणों को छद्मनाम वाले खाता पहचानकर्ता से जोड़ते हैं। उपलब्ध होने पर, हम केवल स्वीकृत कैंपेन नाम, सार्वजनिक लैंडिंग पेज पाथ, रेफ़रर श्रेणियाँ और देश ही रखते हैं। असाइनमेंट की सामग्री, नाम, ईमेल और भुगतान से जुड़े गोपनीय विवरण एनालिटिक्स प्रदाताओं को नहीं भेजे जाते। पेज के नीचे दिए गए कंट्रोल से वैकल्पिक एनालिटिक्स बंद करें। Do Not Track और Global Privacy Control वैकल्पिक डेटा संग्रह बंद कर देते हैं।",
    "آپ کی اجازت سے، ہم ایک فرضی شناخت والے براؤزر شناخت کنندہ کے ذریعے عوامی صفحات کے دوروں اور جائزہ لینے، سائن اپ اور چیک آؤٹ کے مراحل کی پیمائش کرتے ہیں۔ تصدیق کے بعد، ہم ان مراحل کو ایک فرضی شناخت والے اکاؤنٹ شناخت کنندہ سے منسلک کرتے ہیں۔ دستیاب ہونے پر، ہم صرف منظور شدہ مہم کے نام، عوامی لینڈنگ پیج کے راستے، ریفرر کی اقسام اور ملک محفوظ رکھتے ہیں۔ اسائنمنٹ کا مواد، نام، ای میل پتے اور ادائیگی کے خفیہ کوائف تجزیاتی سروس فراہم کرنے والوں کو نہیں بھیجے جاتے۔ صفحے کے نیچے موجود کنٹرول سے اختیاری تجزیات بند کریں۔ Do Not Track اور Global Privacy Control اختیاری ڈیٹا جمع کرنے کو بند کر دیتے ہیں۔",
    "Với sự cho phép của bạn, chúng tôi đo lường lượt truy cập trang công khai và các bước đánh giá, đăng ký và thanh toán bằng một mã nhận dạng trình duyệt giả danh. Sau khi xác minh, chúng tôi liên kết các bước này với một mã nhận dạng tài khoản giả danh. Khi có thể, chúng tôi chỉ lưu tên chiến dịch đã được phê duyệt, đường dẫn trang đích công khai, danh mục trang giới thiệu và quốc gia. Nội dung bài tập, tên, email và thông tin bí mật về thanh toán không được gửi cho các nhà cung cấp dịch vụ phân tích. Tắt tính năng phân tích tùy chọn bằng nút điều khiển ở cuối trang. Do Not Track và Global Privacy Control sẽ tắt việc thu thập dữ liệu tùy chọn.",
    "经您许可，我们会使用一个假名化的浏览器标识符，统计公开页面访问量以及评估、注册和结账步骤。验证后，我们会将这些步骤与一个假名化的账户标识符关联。条件允许时，我们只保留已批准的活动名称、公开落地页路径、引荐来源类别和国家/地区。作业内容、姓名、电子邮件和支付机密信息不会发送给分析服务提供商。您可以通过页面底部的控件关闭可选分析。Do Not Track 和 Global Privacy Control 会停用可选数据收集。"
  ],
  "Journey events are kept for 90 days and payment reporting records for 400 days, with daily cleanup. Payment attribution is removed after 90 days. Account attribution is cleared after 90 days of inactivity, and inactive account reporting records after 400 days. These pseudonymous records are server-only and available only to authorized administrators. Existing accounting and entitlement records follow their separate retention rules.": [
    "यात्रा संबंधी इवेंट 90 दिनों तक और भुगतान रिपोर्टिंग रिकॉर्ड 400 दिनों तक रखे जाते हैं; इनकी रोज़ाना सफ़ाई की जाती है। भुगतान एट्रिब्यूशन 90 दिनों के बाद हटा दिया जाता है। 90 दिनों की निष्क्रियता के बाद खाता एट्रिब्यूशन साफ़ कर दिया जाता है, और निष्क्रिय खातों के रिपोर्टिंग रिकॉर्ड 400 दिनों के बाद हटा दिए जाते हैं। ये छद्मनाम वाले रिकॉर्ड केवल सर्वर पर रखे जाते हैं और केवल अधिकृत प्रशासकों के लिए उपलब्ध हैं। मौजूदा लेखांकन और अधिकार-संबंधी रिकॉर्ड के लिए अलग-अलग प्रतिधारण नियम लागू होते हैं।",
    "صارف کے سفر سے متعلق واقعات 90 دن اور ادائیگی کی رپورٹنگ کے ریکارڈ 400 دن تک محفوظ رکھے جاتے ہیں، اور انہیں روزانہ صاف کیا جاتا ہے۔ ادائیگی سے متعلق انتساب 90 دن بعد ہٹا دیا جاتا ہے۔ 90 دن تک غیر فعال رہنے کے بعد اکاؤنٹ سے متعلق انتساب صاف کر دیا جاتا ہے، اور غیر فعال اکاؤنٹس کے رپورٹنگ ریکارڈ 400 دن بعد ہٹا دیے جاتے ہیں۔ یہ فرضی شناخت والے ریکارڈ صرف سرور پر ہوتے ہیں اور صرف مجاز منتظمین کو دستیاب ہیں۔ موجودہ اکاؤنٹنگ اور استحقاق کے ریکارڈ پر ان کے الگ برقرار رکھنے کے قواعد لاگو ہوتے ہیں۔",
    "Các sự kiện hành trình được lưu trong 90 ngày và hồ sơ báo cáo thanh toán trong 400 ngày; dữ liệu được dọn dẹp hằng ngày. Thông tin phân bổ thanh toán sẽ bị xóa sau 90 ngày. Thông tin phân bổ tài khoản được xóa sau 90 ngày không hoạt động; hồ sơ báo cáo của tài khoản không hoạt động được xóa sau 400 ngày. Các hồ sơ giả danh này chỉ được lưu trên máy chủ và chỉ quản trị viên được ủy quyền mới có thể truy cập. Hồ sơ kế toán và quyền lợi hiện có tuân theo các quy định lưu trữ riêng.",
    "用户旅程事件保留 90 天，支付报告记录保留 400 天，并每日清理。支付归因信息在 90 天后删除。账户归因信息在账户连续 90 天不活跃后清除；不活跃账户的报告记录在 400 天后删除。这些假名化记录仅存储在服务器上，且只有授权管理员可以访问。现有会计记录和权益记录遵循各自的保留规则。"
  ],
